stages.sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_vhsTex;
float4 amzSample_vhsTex(float2 uv) { return float4(amzt_vhsTex.eval((float2(uv.x,1.0-uv.y)*float2(1080.0,1080.0)))); }
float4 amzSample_fontTex(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_bufferA;
float4 amzSample_bufferA(float2 uv) { return float4(amzt_bufferA.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_bufferB;
float4 amzSample_bufferB(float2 uv) { return float4(amzt_bufferB.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_vhsTex(uv);if(tex==2) return amzSample_fontTex(uv);if(tex==3) return amzSample_bufferA(uv);if(tex==4) return amzSample_bufferB(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_preset;
uniform float amzp_intensity;
uniform float amzp_speed;
layout(color) uniform half4 amzp_tint;
uniform float amzp_vhsTexOpacity;






        float hash(float2 p) {
            float3 p3  = fract(float3(p.xyx) * .1031);
            p3 += dot(p3, p3.yzx + 33.33);
            return fract((p3.x + p3.y) * p3.z);
        }

        float noise(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            float2 u = f*f*(3.0-2.0*f);
            return mix( mix( hash( i + float2(0.0,0.0) ), 
                             hash( i + float2(1.0,0.0) ), u.x),
                        mix( hash( i + float2(0.0,1.0) ), 
                             hash( i + float2(1.0,1.0) ), u.x), u.y);
        }

        float noiseTex(float2 uv) {
            return noise(uv * 15.0);
        }


        float2 FontFromScreen(in float2 tpos, in float fontSize, in float2 charPos) {
            return (tpos / fontSize + charPos + 0.5) / 16.0;
        }

        int IntToAscii(in int x) {
            return x + 48;
        }

        float3 DrawCharacterOnScreen(in float2 fragCoord, in int characterID, in float2 letterPositionOnScreen, in float fontSize) {
            float2 letterPosition = (fragCoord - screen.zw * letterPositionOnScreen);

            int cx = characterID - (characterID / 16) * 16;
            int cy = 15 - characterID / 16;
            float2 charPosition = float2(float(cx), float(cy));

            float2 uv = FontFromScreen(letterPosition, fontSize, charPosition);

            float rLetter = 1.0 - amzTexture(2, uv).x;
            float gLetter = 1.0 - amzTexture(2, uv + 0.002).x;
            float bLetter = 1.0 - amzTexture(2, uv - 0.002).x;

            float3 letter = float3(rLetter, gLetter, bLetter);
            float2 boxSize = abs(letterPosition) - 0.5 * fontSize;

            float rBoxValue = step(rLetter, max(boxSize.x, boxSize.y));
            float gBoxValue = step(gLetter, max(boxSize.x, boxSize.y));
            float bBoxValue = step(bLetter, max(boxSize.x, boxSize.y));

            return ((float3(1.0) - float3(rBoxValue, gBoxValue, bBoxValue)) * (float3(1.0) - float3(rLetter, gLetter, bLetter)));
        }


        float rand3(float2 co){
            return fract(sin(dot(co.xy ,float2(12.9898,78.233))) * 43758.5453);
        }

        float2 warpSmart(float2 uv, float offsetValue, float currentTime) {
            bool bendTop    = (offsetValue == 4.0);
            bool bendBottom = (offsetValue == -0.3);
            bool noBend     = (offsetValue == 0.5);

            if (noBend || (!bendTop && !bendBottom)) return uv;

            float baseStrength = 0.4 + 0.4 * rand3(float2(floor(currentTime / 2.0), 123.0));
            float jitter = 5.3 * sin(currentTime * 45.7 + 1.3);
            float strength = clamp(baseStrength + jitter, -1.0, 0.5) * amzp_intensity;

            float curve;
            if (bendTop) {
                float curveRand = rand3(float2(floor(currentTime / 1.5), 456.0));
                curve = 7.0 + curveRand * 5.0;  
            } else {
                curve = 8.0;
            }

            float localT = 0.0;
            float offset = 0.0;

            if (bendTop) {
                if (uv.y <= 0.5) return uv;
                localT = (uv.y - 0.5) * 2.0;
                offset = -strength * pow(localT, curve);
            }
            else if (bendBottom) {
                if (uv.y >= 0.5) return uv;
                localT = (0.5 - uv.y) * 2.0;
                offset = +strength * pow(localT, curve);
            }

            uv.x = clamp(uv.x + offset, 0.0, 1.0);
            return uv;
        }





        void pass0() {
            float2 uv = amzScreenNorm();
            float4 col = amzTexture(0, uv);

            if (int(amzp_preset) == 0) {

                float bar = abs(uv.x - 0.5);
                bar = step(bar, 0.425);
                col *= bar;
            } else if (int(amzp_preset) == 2) {

                float3 textCol = float3(0.0);
                float fontSize = 0.06 * screen.zw.y;
                float2 fragCoord = uv * screen.zw;


                float3 currentLetter;
                currentLetter = DrawCharacterOnScreen(fragCoord, 80, float2(0.1, 0.85), fontSize); 
                textCol += currentLetter;
                currentLetter = DrawCharacterOnScreen(fragCoord, 76, float2(0.13, 0.85), fontSize); 
                textCol += currentLetter;
                currentLetter = DrawCharacterOnScreen(fragCoord, 65, float2(0.16, 0.85), fontSize); 
                textCol += currentLetter;
                currentLetter = DrawCharacterOnScreen(fragCoord, 89, float2(0.19, 0.85), fontSize); 
                textCol += currentLetter;

                col.rgb += textCol;
            } else if (int(amzp_preset) == 3) {
                float targetAspect = 4.0 / 3.0;
                float currentAspect = screen.zw.x / screen.zw.y;

                float2 center = float2(0.5, 0.5);

                if (currentAspect > targetAspect) {
                    float scale = currentAspect / targetAspect;
                    uv.x = (uv.x - center.x) * scale + center.x;
                    if (uv.x < 0.0 || uv.x > 1.0) {
                        col = float4(0.0, 0.0, 0.0, 1.0);
                    }
                } else {
                    float scale = targetAspect / currentAspect;
                    uv.y = (uv.y - center.y) * scale + center.y;
                    if (uv.y < 0.0 || uv.y > 1.0) {
                        col = float4(0.0, 0.0, 0.0, 1.0);
                    }
                }

                if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
                    float2 adjustedFragCoord = uv * screen.zw;
                    float4 texColor = float4(0.0);

                    for(int g = 0; g < 3; g++){
                        float timeOffset    = float(g) * 0.016;
                        float ghostWeight   = 1.0 / 3.0;
                        float currentTime   = (time * amzp_speed) - timeOffset;

                        float2 samplePosition = adjustedFragCoord.xy / screen.zw;
                        samplePosition.y += (rand3(float2(currentTime)) - 0.5) / 18.0;

                        float horizontalJitter = (rand3(float2(currentTime, adjustedFragCoord.y)) - 0.5) / 64.0;

                        float timeSegment = floor(currentTime / 1.5);
                        float valueIndex  = rand3(float2(timeSegment, 456.0));
                        float offsetValue;

                        if (valueIndex < 0.6) {
                            offsetValue = 4.0;   
                        } else if (valueIndex < 0.7) {
                            offsetValue = -0.3; 
                        } else {
                            offsetValue = 0.5; 
                        }

                        float whiteNoiseOffset = (rand3(float2(currentTime * 0.5)) - offsetValue) * 0.22;
                        float adjustedY = samplePosition.y + whiteNoiseOffset;

                        float bwBandOffset = (rand3(float2(currentTime * 0.7 + 200.0)) - 0.5) * 2.5;
                        float bwBandY = samplePosition.y + bwBandOffset;
                        float bwBandPattern = rand3(float2(floor(bwBandY * 3.0), currentTime * 0.05));
                        bool isInBWBand = bwBandPattern > 0.6;

                        float colorNoiseOffset = (rand3(float2(currentTime * 0.7 + 100.0)) - 0.5) * 12.25;

                        float2 noiseSamplePos = samplePosition;
                        noiseSamplePos.x += horizontalJitter;

                        float whiteNoise = rand3(float2(floor(adjustedY * 1500.0),
                                                    floor(noiseSamplePos.x * 50.0)) + float2(currentTime, 0.0));

                        float2 warpUV = samplePosition;
                        warpUV = warpSmart(warpUV, offsetValue, currentTime);

                        if (whiteNoise > 15.5 - 50.0 * adjustedY || whiteNoise < 1.5 - 5.0 * adjustedY) {
                            float2 pixelatedPos = warpUV;
                            float pixelBlockSize = 200.0;
                            pixelatedPos = floor(pixelatedPos * pixelBlockSize) / pixelBlockSize;

                            float aberrationAmount = 0.004 * amzp_intensity;
                            float2 aberrationOffset = float2(aberrationAmount, 0.0);
                            float r = amzTexture(0, pixelatedPos - aberrationOffset).r;
                            float g = amzTexture(0, pixelatedPos).g;
                            float b = amzTexture(0, pixelatedPos + aberrationOffset).b;
                            float4 frameColor = float4(r, g, b, 1.0);

                            float2 pixelSize = 1.0 / screen.zw;
                            float4 sharpenKernel = float4(0.0);
                            sharpenKernel += amzTexture(0, pixelatedPos + float2(-pixelSize.x, 0.0)) * -0.25;
                            sharpenKernel += amzTexture(0, pixelatedPos + float2( pixelSize.x, 0.0)) * -0.25;
                            sharpenKernel += amzTexture(0, pixelatedPos + float2(0.0, -pixelSize.y)) * -0.25;
                            sharpenKernel += amzTexture(0, pixelatedPos + float2(0.0,  pixelSize.y)) * -0.25;
                            sharpenKernel += frameColor * 2.0;
                            frameColor = mix(frameColor, sharpenKernel, 1.0);

                            frameColor.rgb = floor(frameColor.rgb * 24.0) / 24.0;

                            float3 myTint = float3(0.88, 0.94, 1.12);
                            frameColor.rgb *= myTint;

                            float brightnessBoost = 1.0 / max(max(myTint.r, myTint.g), myTint.b);
                            frameColor.rgb *= brightnessBoost * 0.98;
                            frameColor.rgb = clamp(frameColor.rgb, 0.0, 1.0);

                            if (isInBWBand) {
                                float gray = dot(frameColor.rgb, float3(0.299, 0.587, 0.114));
                                float desatAmount = 0.8;
                                frameColor.rgb = mix(frameColor.rgb, float3(gray), desatAmount);
                            }

                            texColor += frameColor * ghostWeight;
                        } else {
                            float staticNoise = rand3(adjustedFragCoord.xy + float2(currentTime * 10.0, 0.0));
                            float2 jitteredTextureSample = samplePosition;
                            jitteredTextureSample.x += horizontalJitter;
                            float4 backgroundTexture = amzTexture(0, jitteredTextureSample);

                            float colorNoiseY = adjustedFragCoord.y + colorNoiseOffset * screen.zw.y;
                            float4 colorNoise = (float4(-0.5) + float4(
                                rand3(float2(colorNoiseY, currentTime)),
                                rand3(float2(colorNoiseY, currentTime + 1.0)),
                                rand3(float2(colorNoiseY, currentTime + 2.0)), 0.0)) * 2.5;

                            float4 noiseColor = float4(staticNoise) * 0.9
                                            + float4(2.0) * 0.17
                                            + colorNoise * 0.5
                                            + backgroundTexture * 0.2;

                            texColor += noiseColor * ghostWeight;
                        }
                    }
                    col = mix(texColor, texColor * float4(amzp_tint.rgb, 1.0), 0.5);
                }
            } else if (int(amzp_preset) == 4) {

                col = amzTexture(0, uv);
            }

            amzOutput = col;
        }







        float3 CA(int tex, float2 uv) {
            float str = 0.01 * amzp_intensity;
            float r = amzTexture(tex, uv + float2(0.0, str)).r;
            float g = amzTexture(tex, uv).g;
            float b = amzTexture(tex, uv + float2(0.0, -str)).b;
            return float3(r, g, b);
        }

        float3 Sharpen(int tex, float2 uv) {
            float str = 0.0075 * amzp_intensity;
            float3 tl = CA(tex, uv + float2(-str, str));
            float3 tm = CA(tex, uv + float2(0.0, str));
            float3 tr = CA(tex, uv + float2(str, str));
            float3 ml = CA(tex, uv + float2(-str, 0.0));
            float3 mr = CA(tex, uv + float2(str, 0.0));
            float3 bl = CA(tex, uv + float2(-str, -str));
            float3 bm = CA(tex, uv + float2(0.0, -str));
            float3 br = CA(tex, uv + float2(str, -str));
            float3 final = (tl + tm + tr + ml + mr + bl + bm + br) / 8.0;
            final = mix(amzTexture(tex, uv).rgb, final, -2.0);
            return final;
        }

        float3 Blur(int tex, float2 uv) {
            float str = 0.0025;
            float3 tl = Sharpen(tex, uv + float2(-str, str));
            float3 tm = Sharpen(tex, uv + float2(0.0, str));
            float3 tr = Sharpen(tex, uv + float2(str, str));
            float3 ml = Sharpen(tex, uv + float2(-str, 0.0));
            float3 mr = Sharpen(tex, uv + float2(str, 0.0));
            float3 bl = Sharpen(tex, uv + float2(-str, -str));
            float3 bm = Sharpen(tex, uv + float2(0.0, -str));
            float3 br = Sharpen(tex, uv + float2(str, -str));
            float3 final = (tl + tm + tr + ml + mr + bl + bm + br) / 8.0;
            return final;
        }

        float2 DistortUV(float2 uv) {
            float offs = noiseTex(float2(time * amzp_speed, uv.y * 0.5));
            offs -= 0.5;
            offs *= 2.0;
            offs *= 0.0025 * amzp_intensity;
            uv.x += offs;
            return uv;
        }

        float3 ColourCorrect(float3 col) {
            col += 0.1;
            col = clamp(col, float3(0.0), float3(1.0));
            col = pow(col, float3(0.8));
            col /= 1.5;
            col = clamp(col, float3(0.0), float3(1.0));
            return col;
        }

        float3 Finalize(float3 col, float2 uv) {
            float bars = noiseTex(float2(time * amzp_speed, uv.y * 0.1));
            col += float3(bars) * float3(0.05, 0.01, 0.005) * amzp_intensity;
            float n = noiseTex(uv * 0.45 + (time * amzp_speed * noiseTex(float2(time * amzp_speed))));
            n *= 0.05 * amzp_intensity;
            return (col * n) + col / 1.1;
        }


        float bendscale = 1.4;

        float Random(float2 co, float inty) {
            return inty * fract(sin((time * amzp_speed) * dot(co.xy, float2(12.9898, 78.233))) * 43758.5453);
        }

        float3 LoadTextureWithFilter(int tex, float2 UV) {
            float2 fragCoord = UV * screen.zw;

            float2 rOffset = float2(-0.001, -0.0005) * amzp_intensity;
            float2 bOffset = float2(0.001, 0.001) * amzp_intensity;

            float sharpenFactor = 1.5;

            float upR = amzTexture(tex, (fragCoord + float2(0.0, 1.0)) / screen.zw + rOffset).r;
            float upG = amzTexture(tex, (fragCoord + float2(0.0, 1.0)) / screen.zw).g;
            float upB = amzTexture(tex, (fragCoord + float2(0.0, 1.0)) / screen.zw + bOffset).b;

            float leftR = amzTexture(tex, (fragCoord + float2(-1.0, 0.0)) / screen.zw + rOffset).r;
            float leftG = amzTexture(tex, (fragCoord + float2(-1.0, 0.0)) / screen.zw).g;
            float leftB = amzTexture(tex, (fragCoord + float2(-1.0, 0.0)) / screen.zw + bOffset).b;

            float centerR = amzTexture(tex, fragCoord / screen.zw + rOffset).r;
            float centerG = amzTexture(tex, fragCoord / screen.zw).g;
            float centerB = amzTexture(tex, fragCoord / screen.zw + bOffset).b;

            float rightR = amzTexture(tex, (fragCoord + float2(1.0, 0.0)) / screen.zw + rOffset).r;
            float rightG = amzTexture(tex, (fragCoord + float2(1.0, 0.0)) / screen.zw).g;
            float rightB = amzTexture(tex, (fragCoord + float2(1.0, 0.0)) / screen.zw + bOffset).b;

            float downR = amzTexture(tex, (fragCoord + float2(0.0, -1.0)) / screen.zw + rOffset).r;
            float downG = amzTexture(tex, (fragCoord + float2(0.0, -1.0)) / screen.zw).g;
            float downB = amzTexture(tex, (fragCoord + float2(0.0, -1.0)) / screen.zw + bOffset).b;

            return (1.0 + 4.0 * sharpenFactor) * float3(centerR, centerG, centerB) -
                sharpenFactor * (float3(upR, upG, upB) + float3(leftR, leftG, leftB) + float3(rightR, rightG, rightB) + float3(downR, downG, downB));
        }

        float2 screenDistort(float2 uv) {
            uv -= float2(0.5, 0.5);
            uv = uv * bendscale * (1.0 / 1.2 + 2.0 * uv.x * uv.x * uv.y * uv.y);
            uv += float2(0.5, 0.5);
            return uv;
        }

        float2 scale2D(float2 uv, float2 scale) {
            float2x2 scaleMatrix = float2x2(scale.x, 0.0, 0.0, scale.y);
            return uv * scaleMatrix;
        }

        float box(float2 st, float2 amzLocal_size, float _smoothEdges) {
            amzLocal_size = float2(0.5) - amzLocal_size * 0.5;
            float2 aa = float2(_smoothEdges * 0.5);
            float2 uv = smoothstep(amzLocal_size, amzLocal_size + aa, st);
            uv *= smoothstep(amzLocal_size, amzLocal_size + aa, float2(1.0) - st);
            return uv.x * uv.y;
        }

        float horizontalBar(float amzLocal_pos, float uvY, float offset) {
            float barRange = 0.05;
            float edge0 = (amzLocal_pos - barRange);
            float edge1 = (amzLocal_pos + barRange);

            float x = smoothstep(edge0, amzLocal_pos, uvY) * offset;
            x -= smoothstep(amzLocal_pos, edge1, uvY) * offset;
            return x;
        }


        float3 rgb2yiq(float3 rgb) {
            return float3x3(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312) * rgb;
        }

        float3 yiq2rgb(float3 yiq) {
            return float3x3(1.000, 1.000, 1.000, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703) * yiq;
        }

        float2x2 rotate2D(float t) {
            return float2x2(cos(t), sin(t), -sin(t), cos(t));
        }

        float3 vhsTex2D(float2 uv, float rot) {
            float3 yiq = float3(0.0);
            int SAMPLES = 6;

            for (int i = 0; i < 6; i++) {
                yiq += (rgb2yiq(amzTexture(3, uv - float2(float(i), 0.0) / float2(320.0, 240.0)).xyz) *
                       float2(float(i), float(SAMPLES - 1 - i)).yxx / float(SAMPLES - 1)) / float(SAMPLES) * 2.0;
            }
            if (rot != 0.0) { yiq.yz = rotate2D(rot) * yiq.yz; }
            return yiq2rgb(yiq);
        }

        void pass1() {
            float2 uv = amzScreenNorm();
            float alpha = amzTexture(3, uv).a;

            if (int(amzp_preset) == 0) {

                uv = DistortUV(uv);
                float3 colour = Blur(3, uv);
                colour = ColourCorrect(colour);
                colour = Finalize(colour, uv);
                colour = mix(colour, colour * amzp_tint.rgb, 0.5);
                amzOutput = float4(colour, alpha);

            } else if (int(amzp_preset) == 1) {

                float3 pixelColor = float3(0.0, 0.0, 1.0);

                float2 distUV = screenDistort(uv);
                distUV = scale2D(distUV, float2(0.85));
                distUV += float2(0.075, 0.075);

                float offsetIntensity = 0.001 * amzp_intensity;
                for (float i = 0.0; i < 1.0; i += 0.1) {
                    float d = mod((time * amzp_speed) * i, 1.7);
                    float o = sin(1.0 - tan((time * amzp_speed) * 0.24 * i));
                    o *= offsetIntensity;
                    distUV.x += horizontalBar(d, distUV.y, o);
                }

                pixelColor = LoadTextureWithFilter(3, distUV);


                float fontSize = 0.1 * screen.zw.y;
                float blink = step(0.5, (sin(5.0 * (time * amzp_speed)) + 1.0) / 2.0);
                float3 currentLetter;
                float2 fragCoord = distUV * screen.zw;

                currentLetter = DrawCharacterOnScreen(fragCoord, 3, float2(0.1, 0.85), fontSize);
                pixelColor += (currentLetter * blink * float3(1.0, 0.0, 0.0));
